window.LEDGER = (function () { const SRC = { va: { t: "Department of Veterans Affairs, America's Wars fact sheet (Nov 2023)", u: "https://www.va.gov/opa/publications/factsheets/fs_americas_wars.pdf", covers: "US military battle deaths and other in-service deaths for every major war through 1991. Figures come from the Defense Department." }, crs: { t: "Congressional Research Service, Costs of Major U.S. Wars (RS22926, June 2010)", u: "https://www.everycrsreport.com/reports/RS22926.html", covers: "Military operations cost of each major war in constant FY2011 dollars. Excludes veterans' benefits, interest on war debt, and aid to allies." }, hacker: { t: "J. David Hacker, A Census-Based Count of the Civil War Dead, Civil War History 57:4 (2011)", u: "https://www.sciencedaily.com/releases/2011/09/110921120124.htm", covers: "Census-based estimate of Civil War dead: 750,000, with a range of 650,000 to 850,000, against the traditional count of about 620,000." }, state: { t: "State Department, Office of the Historian, The Philippine-American War, 1899-1902", u: "https://history.state.gov/milestones/1899-1913/war", covers: "More than 4,200 American and 20,000 Filipino combatants killed, and as many as 200,000 Filipino civilian deaths." }, dod: { t: "Defense Department, Casualty Status report (August 2021)", u: "https://www.defense.gov/casualty.pdf", covers: "US military deaths by named operation: Iraqi Freedom 4,418, New Dawn 74, Enduring Freedom and Freedom's Sentinel in Afghanistan." }, brownCost: { t: "Brown University, Costs of War project, budgetary costs of the post-9/11 wars (Sept 2021)", u: "https://costsofwar.watson.brown.edu/overview", covers: "About $8 trillion in total: $2.3 trillion for the Afghanistan and Pakistan war zone, $2.1 trillion for Iraq and Syria, plus homeland security, interest, and $2.2 trillion in future veterans' care." }, brownHuman: { t: "Brown University, Costs of War project, human costs", u: "https://watson.brown.edu/costsofwar/costs/human", covers: "At least 940,000 people killed by direct war violence across the post-9/11 war zones." }, drug: { t: "Fortune, U.S. spending on the War on Drugs tops $1 trillion (Feb 2026)", u: "https://fortune.com/2026/02/23/us-trillion-dollar-drug-war-rising-use/", covers: "Cumulative drug war spending since 1971 estimated at more than $1 trillion. Advocacy and think-tank estimates agree on the order of magnitude; there is no official tally." }, bls: { t: "Bureau of Labor Statistics, Consumer Price Index (CPI-U annual averages)", u: "https://www.bls.gov/cpi/", covers: "Used to restate 2011 dollars in 2025 dollars: 224.939 for 2011 and about 322.6 for 2025, a factor of 1.434." }, sp: { t: "The Sentencing Project, Locked Out reports (2020 and 2024)", u: "https://www.sentencingproject.org/reports/locked-out-2024-four-million-denied-voting-ri", covers: "Felony disenfranchisement by state and race. In 2020 the Black rate exceeded 20 percent in Tennessee and Wyoming; nationally one in 22 Black adults was barred in 2024." }, enlist: { t: "Associated Press via NPR, Black Military Enlistment Takes Nosedive (June 2007)", u: "https://www.npr.org/sections/newsandviews/2007/06/black_military_enlistment_take.html", covers: "Black recruits fell nearly 40 percent from 2001 to 2006; Black share of Army recruits fell from over 20 percent to about 12 percent." }, cbs: { t: "CBS News, Fewer Blacks Enlisting In Military", u: "https://www.cbsnews.com/news/fewer-blacks-enlisting-in-military/", covers: "Polling on the Iraq war by race: disapproval among Black respondents ran far above the national figure." }, vietShare: { t: "Mother Jones on Pentagon casualty data by race, 1961-65 (Jan 2026)", u: "https://www.motherjones.com/politics/2026/01/history-month-black-military-service-vietnam-war-heroes-dei-recruiting-hegseth-trump-defense/", covers: "Pentagon data released in 1966: Black troops were under 15 percent of the Army in Vietnam and more than 18 percent of deaths in 1961-65. Other commonly cited figures put the 1965 share near 25 percent." }, legion: { t: "American Legion, 10 facts about African-American military service", u: "https://legion.org/node/244754", covers: "24 percent of the roughly 500,000 US personnel deployed in the Persian Gulf War were African American." }, vietAll: { t: "Vietnam War casualties (summary of Lewy, Vietnamese government, and demographic estimates)", u: "https://en.wikipedia.org/wiki/Vietnam_War_casualties", covers: "Total deaths from about 1.35 million (Lewy, 1965-74) to over 3 million (Vietnamese government, 1955-75)." }, koreaAll: { t: "Peace Research Institute Oslo estimates, summarized in War crimes in the Korean War", u: "https://www.wikipedia.org/wiki/War_crimes_in_the_Korean_War", covers: "About 3 million total deaths, most of them civilians, with a range of 1.5 to 4.5 million." } }; const LENS = [ { k: "Overall", note: "Blue is a net expansion of democracy at home; red is a net restriction.", rule: "A summary judgment across the other six columns, weighted toward lasting legal and institutional change over temporary wartime measures." }, { k: "Civil liberties", note: "Speech, surveillance and detention. Red means liberties were cut back.", rule: "Loss if the war produced new limits on speech, new surveillance, or detention without trial that outlasted the fighting. Gain if it produced lasting new protections." }, { k: "Formal rights", note: "Who could vote and who counted as a citizen.", rule: "Gain if the franchise or citizenship widened as a direct result. Loss if a group was stripped of rights or placed under US rule without them." }, { k: "Executive power", note: "Red means war-making power shifted toward the president.", rule: "Loss if the president started, widened, or sustained the war with less consent from Congress or the courts than before. Gain if the war ended with tighter checks." }, { k: "Black Americans", note: "Scored on what the war meant for Black Americans specifically.", rule: "Weighs what service earned against what veterans and communities came home to, and whether any lasting gain followed within a generation." }, { k: "Economic cost", note: "Blue means broad benefit at home; red means costs that crowded out domestic needs.", rule: "Gain if the war economy left broad, lasting benefits. Loss if spending displaced domestic programs or was financed by debt with little return." }, { k: "Policing", note: "Red means policing at home became more militarized or intrusive.", rule: "Loss if military tactics, equipment, or intelligence methods moved into domestic policing. Gain if policing became less militarized or more accountable." } ]; const OFF = "Official count", SCH = "Scholarly estimate", ROUGH = "Rough estimate"; const WARS = [ { n: "Revolutionary War", y: "1775–83", t: "1775", c: [-73, 42.5], r: [840], v: "ggggmmn", deaths: { lo: 4435, hi: 4435, tag: OFF, note: "Battle deaths only. Counting disease and captivity, historians put the total near 25,000.", src: "va" }, cost: { b2011: 2.407, tag: ROUGH, note: "From an 1895 financial history, restated by CRS.", src: "crs" }, all: null, d: [ "The war replaced a monarchy with an elected republic and a written constitution. The promise was narrow at first: voting was mostly limited to white men with property, and slavery survived the founding.", "The Bill of Rights followed in 1791, protecting speech, press, assembly and due process. During the war itself Loyalists faced confiscation and mob violence, so the protections came after the fighting.", "States wrote constitutions with elected legislatures, and some dropped religious tests for office. Most kept property requirements, and women, Native people and nearly all Black people were left out.", "The founders had just fought a king, so they gave Congress the power to declare war and fund armies. The president commands the military but was meant to need Congress to start a war.", ["About 5,000 Black soldiers fought for independence, and thousands more fled to British lines.", "Slavery was protected in the Constitution through the three-fifths and fugitive clauses.", "Northern states began gradual emancipation, starting with Vermont in 1777.", "Both sides offered freedom for service, and more enslaved people sought it with the British than with the Patriots."], "The war left heavy debts and nearly worthless paper money. Farmers' revolts like Shays' Rebellion followed, and the debt crisis drove the push for a federal government with taxing power.", "There were no police forces in the modern sense. In the South, slave patrols already did the work of surveillance and control, and the war left them in place." ], ref: ["US Constitution (1787)", "Bill of Rights, ratified 1791", "State constitutions of 1776–80; Keyssar, The Right to Vote", "US Constitution, Article I, Section 8", "Quarles, The Negro in the American Revolution; Constitution, Art. I §2 and Art. IV §2", "Holton, Unruly Americans and the Origins of the Constitution", "Hadden, Slave Patrols"] }, { n: "War of 1812", y: "1812–15", t: "1812", c: [-81, 45], r: [840, 124], v: "mnmmmmn", deaths: { lo: 2260, hi: 2260, tag: OFF, note: "Battle deaths only. Totals including disease are usually put at 15,000 to 20,000.", src: "va" }, cost: { b2011: 1.553, tag: SCH, note: "Rise in Army and Navy spending over the prewar average.", src: "crs" }, all: null, d: [ "The war ended in a draw and changed little in how the country was governed. Its main lasting effect was on the frontier, where the defeat of Tecumseh's confederacy opened the way for removal.", "Opposition was loud, especially in New England, and went mostly unpunished. No federal sedition law was passed this time, in contrast to 1798.", "In the years after the war, states dropped property requirements and white men gained near-universal suffrage. Several of the same states took the vote away from free Black men in the process.", "Madison asked Congress for a declaration and got one, the first under the Constitution. Jackson's martial law in New Orleans, kept in place after the fighting ended, showed how far a general could go.", ["Black sailors served throughout the Navy, and free Black battalions fought under Jackson at New Orleans.", "Jackson had promised land and equal pay, and the promises went largely unmet.", "About 4,000 enslaved people escaped to British lines and were resettled as free people.", "For many Black Americans the British side was the path to freedom, as it had been in the Revolution."], "The British blockade and the earlier embargo crushed trade and hit port cities hard. Cut off from imports, the North built its first textile mills, which seeded American manufacturing.", "No meaningful change in policing came out of this war." ], ref: ["Taylor, The Civil War of 1812", "Hickey, The War of 1812: A Forgotten Conflict", "Keyssar, The Right to Vote", "Declaration of War, June 18, 1812; Warshauer, Andrew Jackson and the Politics of Martial Law", "Taylor, The Internal Enemy; Smith, The Slaves' Gamble", "Hickey, The War of 1812", "No source needed: no change recorded"] }, { n: "Indian Wars", y: "1780s–1890s", t: "1817", c: [-104, 43], r: [840], v: "llllmml", deaths: { lo: 1000, hi: 1000, tag: ROUGH, note: "VA estimate of US battle deaths, 1817–98. Native deaths were far higher and are not counted here.", src: "va" }, cost: { b2011: null, tag: null, note: "Not in the CRS table. No reliable total exists.", src: null }, all: null, d: [ "A century of campaigns pushed Native nations off their land through force and broken treaties. This was expansion by conquest inside what became US borders.", "Treaties were signed and then ignored when land was wanted. The removals of the 1830s forced tens of thousands of people west, and thousands died on the way.", "Native people were treated as members of separate nations when convenient and as wards when not. Citizenship did not come until 1924, and some states blocked Native voting for decades after.", "When the Supreme Court sided with the Cherokee in 1832, Jackson declined to enforce the ruling. Removal went ahead, an early case of a president overriding the courts.", ["Buffalo Soldiers made up about a fifth of the frontier cavalry.", "Land taken from the Creek, Cherokee, Choctaw and Chickasaw became the cotton kingdom, and about a million enslaved people were forced south and west to work it.", "Army service gave steady pay and a measure of standing that few other jobs offered.", "Black soldiers were used to enforce a conquest that also expanded slavery, which is the hardest tension in this lens."], "Seized land was sold cheaply to settlers and speculators, building wealth that passed down through white families. The same land extended the plantation economy.", "The Army acted as a police force across the West. Reservations brought agents, pass systems and Indian police, a model of confinement and control." ], ref: ["Ostler, Surviving Genocide", "Indian Removal Act (1830); Saunt, Unworthy Republic", "Indian Citizenship Act (1924)", "Worcester v. Georgia (1832)", "Leckie, The Buffalo Soldiers; Baptist, The Half Has Never Been Told", "Saunt, Unworthy Republic", "Hagan, Indian Police and Judges"] }, { n: "Mexican-American War", y: "1846–48", t: "1846", c: [-102, 24], r: [484], v: "lnlllmn", deaths: { lo: 13283, hi: 13283, tag: OFF, note: "1,733 in battle and 11,550 from other causes, mostly disease.", src: "va" }, cost: { b2011: 2.376, tag: SCH, note: "Rise in Army and Navy spending over the prewar average.", src: "crs" }, all: null, d: [ "The US took about half of Mexico's territory. Deciding whether slavery would spread into it broke the political system within a dozen years.", "Critics, including Lincoln and Thoreau, spoke freely and no speech laws were passed.", "The treaty promised citizenship and property rights to Mexicans who stayed. In practice courts and land commissions stripped many of their land, and their standing as citizens was contested for generations.", "Polk sent troops into disputed territory, then told Congress that war already existed. It became a template for presidents presenting Congress with a fight already under way.", ["Few Black soldiers served. Enslaved men were brought as officers' servants, and some escaped into Mexico, where slavery was illegal.", "The Fugitive Slave Act of 1850 put free Black people in the North at risk of kidnapping.", "The new land reopened the slavery fight and led toward civil war.", "Slaveholders were among the war's strongest backers because they wanted room to expand."], "California gold and new farmland enriched the country. The gains came with a political cost that no budget captured.", "Little national change, though the Texas Rangers' violence against Mexican residents along the border dates from this period." ], ref: ["Greenberg, A Wicked War", "Lincoln's Spot Resolutions (1847); Thoreau, Civil Disobedience (1849)", "Treaty of Guadalupe Hidalgo (1848), Articles VIII–IX", "Polk's war message, May 11, 1846", "Fugitive Slave Act (1850); Baumgartner, South to Freedom", "Greenberg, A Wicked War", "Martinez, The Injustice Never Leaves You"] }, { n: "Civil War", y: "1861–65", t: "1861", c: [-86, 33], r: [840], v: "gmglgmm", deaths: { lo: 620000, hi: 750000, tag: SCH, note: "Both sides. 620,000 is the traditional count; a 2011 census study estimates 750,000. VA's documented total is 498,332 from incomplete Confederate returns.", src: "hacker" }, cost: { b2011: 79.742, tag: SCH, note: "Union $59.6 billion plus Confederacy $20.1 billion in 2011 dollars.", src: "crs" }, all: null, d: [ "The war ended slavery and rewrote the Constitution. It is the clearest case of a war expanding democracy, and also the clearest case of gains being reversed afterward.", "Lincoln suspended habeas corpus and thousands were held by the military. The 14th Amendment that followed became the basis for most modern civil liberties law.", "The 13th Amendment ended slavery, the 14th defined citizenship and equal protection, and the 15th barred racial limits on voting. Black men voted and held office across the South during Reconstruction.", "Lincoln blockaded ports, raised armies and spent money before Congress met. Later presidents cited these acts as precedent for emergency power.", ["About 180,000 Black soldiers fought for the Union.", "Black Codes, Klan terror, and the end of Reconstruction in 1877.", "Emancipation, citizenship and the vote, honored mostly on paper for the next century.", "Reconstruction showed what multiracial democracy could look like, and its overthrow showed how fast it could be undone once federal protection left."], "The Union created a national currency, an income tax, land-grant colleges and the transcontinental railroad. The South's economy was destroyed, and freedpeople got no land, leaving most in sharecropping.", "Federal troops and the new Justice Department prosecuted the Klan in the early 1870s. After 1877 the troops left, and convict leasing and local sheriffs took over the control of Black labor." ], ref: ["Foner, Reconstruction: America's Unfinished Revolution", "Ex parte Merryman (1861); 14th Amendment (1868)", "13th, 14th and 15th Amendments (1865–70)", "The Prize Cases (1863)", "Foner, Reconstruction; Du Bois, Black Reconstruction in America", "Legal Tender Act, Morrill Act, Pacific Railway Act (1862)", "Enforcement Acts (1870–71); Blackmon, Slavery by Another Name"] }, { n: "Spanish-American War", y: "1898", t: "1898", c: [-79, 22], r: [192, 630], v: "lnlllmn", deaths: { lo: 2446, hi: 2446, tag: OFF, note: "385 in battle and 2,061 from other causes. VA dates this entry 1898–1902, so it may overlap the Philippine figure.", src: "va" }, cost: { b2011: 9.034, tag: SCH, note: "Rise in Army and Navy spending over the prewar average.", src: "crs" }, all: null, d: [ "A short war made the US a colonial power holding Puerto Rico, Guam and the Philippines. The country now governed millions of people who had no vote in it.", "The war was popular and brief, and no major restrictions followed at home.", "In the Insular Cases the Supreme Court ruled that the Constitution does not fully apply in the territories. Those rulings still stand and still limit rights in Puerto Rico and Guam.", "The president became the administrator of overseas colonies, run by military governors and appointees.", ["Black regulars fought at San Juan Hill and were praised, then written out of the story.", "In November 1898 white supremacists overthrew the elected government of Wilmington, North Carolina, and Washington did nothing.", "White North and South reunited around empire, and disfranchisement swept the South within a decade.", "The racial thinking used to justify ruling Cubans and Filipinos was the same thinking behind Jim Crow."], "The war was cheap and opened markets in the Caribbean and Pacific. Sugar and shipping interests gained the most.", "Little change at home from this war alone. The larger effect came from the Philippine occupation that followed." ], ref: ["Immerwahr, How to Hide an Empire", "Hoganson, Fighting for American Manhood", "Downes v. Bidwell (1901)", "Treaty of Paris (1898); Foraker Act (1900)", "Zucchino, Wilmington's Lie; Gatewood, Black Americans and the White Man's Burden", "Immerwahr, How to Hide an Empire", "See the Philippine-American War entry"] }, { n: "Philippine-American War", y: "1899–1902", t: "1899", c: [122, 13], r: [608], v: "lllllll", deaths: { lo: 4200, hi: 4200, tag: OFF, note: "State Department figure: more than 4,200 Americans, most from disease.", src: "state" }, cost: { b2011: null, tag: null, note: "Not in the CRS table. Contemporary estimates ran to several hundred million dollars at the time.", src: null }, all: { text: "More than 20,000 Filipino combatants and as many as 200,000 civilians.", src: "state" }, d: [ "The US fought a three-year war against Filipinos who had expected independence. As many as 200,000 civilians died, and methods developed there came back home.", "The Army built a detailed intelligence system to track Filipino leaders. Officers trained in it later ran domestic surveillance of radicals and labor organizers during World War I.", "Filipinos were US nationals with no vote and no path to statehood. Independence was promised and delayed until 1946.", "The occupation ran for years on presidential authority with thin oversight from Congress. Senate hearings on torture, including the water cure, led to few consequences.", ["Four Black regiments were sent to put down the independence movement.", "Soldiers wrote home about hearing the same slurs aimed at Filipinos that they knew from home, while lynching was near its peak.", "The Black press split over empire, and a handful of soldiers, David Fagen the best known, defected to the Filipino side.", "It forced an early version of a lasting question: whether to fight abroad for a country that denied your rights at home."], "The occupation cost far more than the $20 million Spain was paid for the islands. Returns went to a narrow set of trading and plantation interests.", "Historian Alfred McCoy traces a line from the Philippine Constabulary's surveillance files to US police intelligence units. It is the first clear case of colonial policing coming home." ], ref: ["State Department, Office of the Historian; Kramer, The Blood of Government", "McCoy, Policing America's Empire", "Philippine Organic Act (1902); Tydings-McDuffie Act (1934)", "Senate Committee on the Philippines hearings (Lodge Committee, 1902)", "Gatewood, Smoked Yankees and the Struggle for Empire", "Treaty of Paris (1898); Kramer, The Blood of Government", "McCoy, Policing America's Empire"] }, { n: "World War I", y: "1917–18", t: "1917", c: [2, 47], r: [250, 56], v: "mlglmml", deaths: { lo: 116516, hi: 116516, tag: OFF, note: "53,402 in battle and 63,114 from other causes, largely influenza.", src: "va" }, cost: { b2011: 334, tag: SCH, note: "Rise in Army and Navy spending over the prewar average.", src: "crs" }, all: null, d: [ "The war brought the harshest crackdown on dissent the country had seen up to that point. Within two years of its end, women had won the vote.", "The Espionage and Sedition Acts made criticism of the war a crime, and about 2,000 people were prosecuted, including Eugene Debs. The Palmer Raids of 1919 and 1920 rounded up thousands of immigrants and radicals.", "Women's wartime work strengthened the case for suffrage, and the 19th Amendment was ratified in 1920. Black women in the South were still blocked from voting.", "Wilson got authority over railroads, food, fuel and public information. Most agencies closed after the war, but the model of a wartime command economy stayed.", ["More than 350,000 Black soldiers served. The Harlem Hellfighters fought under French command because the US Army would not field them beside white troops.", "In the Red Summer of 1919 white mobs attacked Black communities in more than two dozen cities, and veterans were lynched, some in uniform.", "The Great Migration built northern voting power and a more assertive political voice.", "Du Bois had urged Black Americans to close ranks behind the war. The aftermath convinced many that loyalty would not be repaid."], "War orders created a boom and pulled workers north into factories. A sharp recession hit in 1920, and the income tax became the main source of federal revenue.", "The Bureau of Investigation, later the FBI, grew fast. A young J. Edgar Hoover built files on radicals and Black leaders, Marcus Garvey among them." ], ref: ["Kennedy, Over Here: The First World War and American Society", "Espionage Act (1917); Sedition Act (1918); Debs v. United States (1919)", "19th Amendment (1920)", "Lever Act (1917); Overman Act (1918)", "Williams, Torchbearers of Democracy; McWhirter, Red Summer", "Revenue Act of 1918; Kennedy, Over Here", "Kornweibel, Seeing Red: Federal Campaigns Against Black Militancy"] }, { n: "World War II", y: "1941–45", t: "1941", c: [11, 51], r: [276, 380, 392], v: "mlmlggm", deaths: { lo: 405399, hi: 405399, tag: OFF, note: "291,557 in battle and 113,842 from other causes.", src: "va" }, cost: { b2011: 4104, tag: SCH, note: "Rise in military spending over the prewar average. At its peak the war took 36 percent of GDP.", src: "crs" }, all: null, d: [ "The war produced one of the worst civil liberties violations in US history and a permanent security state. It also opened industry, and eventually the military, to Black Americans and built the middle class.", "About 120,000 Japanese Americans, most of them citizens, were held in camps without charges. The Supreme Court upheld it in Korematsu, and Congress apologized in 1988.", "Soldier-voting laws passed and the Supreme Court struck down the white primary in 1944. Internment showed at the same time that citizenship could be suspended by race.", "The war left a standing military, and the 1947 National Security Act created the Defense Department, the CIA and the National Security Council. Nuclear weapons put the largest decision of all in one person's hands.", ["About 900,000 Black Americans served in segregated units under the banner of the Double V campaign: victory abroad and at home.", "GI Bill benefits were run locally and Black veterans were largely shut out of home loans. Isaac Woodard was blinded by police in 1946, hours after his discharge.", "A. Philip Randolph's threatened march won an executive order opening defense jobs in 1941, and Truman desegregated the military in 1948.", "This is the war where organized pressure extracted the most, and the GI Bill gap is one root of today's wealth gap."], "War production ended the Depression and unemployment fell to about 1 percent. The GI Bill paid for college and home loans for millions, though Black veterans were largely excluded from the housing side.", "The FBI's domestic intelligence role expanded sharply. Street policing changed less, though the 1943 riots in Detroit and Los Angeles showed police siding against Black and Mexican American residents." ], ref: ["Kennedy, Freedom from Fear", "Executive Order 9066 (1942); Korematsu v. United States (1944); Civil Liberties Act (1988)", "Soldier Voting Act (1942); Smith v. Allwright (1944)", "National Security Act (1947)", "Executive Orders 8802 (1941) and 9981 (1948); Katznelson, When Affirmative Action Was White", "Servicemen's Readjustment Act (1944); Katznelson, When Affirmative Action Was White", "Capeci and Wilkerson, Layered Violence: The Detroit Rioters of 1943"] }, { n: "Korean War", y: "1950–53", t: "1950", c: [127, 38], r: [410, 408], v: "mlnlgmn", deaths: { lo: 36574, hi: 36574, tag: OFF, note: "In theater: 33,739 in battle and 2,835 from other causes. Another 17,672 died in service elsewhere.", src: "va" }, cost: { b2011: 341, tag: SCH, note: "Defense spending above the prewar and postwar trend line.", src: "crs" }, all: { text: "About 3 million, most of them Korean civilians (range 1.5 to 4.5 million).", src: "koreaAll" }, d: [ "The war was fought by an integrating military while fear of communism narrowed politics at home.", "McCarthy's hearings, loyalty oaths and blacklists peaked during the war. Thousands of people lost jobs over their associations.", "No significant change in voting or citizenship came from this war.", "Truman called it a police action and never asked Congress for a declaration. Every major war since has followed that pattern, though the Supreme Court did block his seizure of the steel mills.", ["Combat needs ended segregated units in practice, making this the first war fought by an integrated force.", "Segregation at home was untouched, and Du Bois and Paul Robeson were targeted as subversives.", "Integration's success in the ranks strengthened the case behind Brown v. Board in 1954.", "Cold War competition gave civil rights some leverage, while anticommunism narrowed which Black voices were allowed."], "Defense spending roughly tripled and never returned to prewar levels. That permanent budget is what Eisenhower later called the military-industrial complex.", "Little direct change in local policing." ], ref: ["Cumings, The Korean War: A History", "Internal Security Act (1950); Schrecker, Many Are the Crimes", "No source needed: no change recorded", "Youngstown Sheet & Tube Co. v. Sawyer (1952)", "MacGregor, Integration of the Armed Forces 1940–1965; Dudziak, Cold War Civil Rights", "NSC-68 (1950); Eisenhower's farewell address (1961)", "No source needed: no change recorded"] }, { n: "Vietnam War", y: "1955–75", t: "1955", c: [107, 15], r: [704, 418, 116], v: "mlgmlll", deaths: { lo: 58220, hi: 58220, tag: OFF, note: "In theater: 47,434 in battle and 10,786 from other causes.", src: "va" }, cost: { b2011: 738, tag: OFF, note: "Defense Department estimate of the added cost of operations.", src: "crs" }, all: { text: "Estimates run from about 1.35 million to more than 3 million, including Vietnamese civilians.", src: "vietAll" }, d: [ "The government spied on its own citizens and the war consumed money meant for poverty programs. The backlash produced real reforms in the 1970s.", "COINTELPRO targeted King, the Black Panthers and antiwar groups with surveillance and sabotage. Students were shot at Kent State and Jackson State, and the Church Committee later exposed the abuses.", "The 26th Amendment lowered the voting age to 18, on the argument that anyone old enough to be drafted was old enough to vote.", "The Tonkin Gulf Resolution gave Johnson a blank check based on a misreported incident. Congress passed the War Powers Act in 1973, which presidents have largely worked around.", ["Pentagon data showed Black troops were under 15 percent of the Army in Vietnam and more than 18 percent of deaths in 1961–65. Other commonly cited figures put the 1965 share near a quarter.", "King's 1967 Riverside speech cost him allies, and Great Society money dried up.", "Protest pushed the Black share of deaths down to about 12 percent by the war's end, and the draft gave way to an all-volunteer force in 1973.", "Muhammad Ali's refusal and King's break tied the Black freedom struggle to opposition to the war."], "Johnson refused to choose between guns and butter and tried to fund both. Inflation followed, and antipoverty programs were cut back.", "Los Angeles formed the first SWAT team in the 1960s, modeled on military units. Federal grants after 1968 sent money and equipment to local police." ], ref: ["Appy, American Reckoning", "Church Committee Final Report (1976)", "26th Amendment (1971)", "Gulf of Tonkin Resolution (1964); War Powers Resolution (1973)", "Pentagon casualty data (1966); Terry, Bloods; King, Beyond Vietnam (1967)", "Appy, American Reckoning", "Omnibus Crime Control and Safe Streets Act (1968); Balko, Rise of the Warrior Cop"] }, { n: "War on Drugs", y: "1971–present", t: "1971", c: [-74, 4], r: [170, 591], v: "lllmlll", campaign: true, deaths: { lo: null, hi: null, tag: null, note: "Not a military campaign, so there is no comparable count.", src: null }, cost: { bcur: 1000, tag: ROUGH, note: "Cumulative federal, state and local spending since 1971. No official tally exists.", src: "drug" }, all: null, d: [ "Declared by Nixon in 1971 and escalated under Reagan, it applied the language and tools of war to a public health problem. Its costs fell hardest on Black and Latino communities.", "Courts carved drug exceptions into search and seizure protections. No-knock raids, civil asset forfeiture and stop-and-frisk all grew out of drug enforcement.", "Felony convictions cost millions of people the vote. In 2020 more than one in five Black adults in Tennessee and Wyoming was barred from voting.", "The DEA was created in 1973 and a national drug policy office in 1988. Abroad, the campaign was used to justify the 1989 invasion of Panama and military aid to Colombia.", ["No soldiers were drafted. The front line ran through Black and brown neighborhoods.", "Mass incarceration, and a 100-to-1 sentencing gap between crack and powder cocaine from 1986.", "The gap was cut to 18-to-1 in 2010, with partial sentencing reform in 2018.", "Black and white Americans use drugs at similar rates, and Black Americans have been imprisoned for it at several times the rate."], "Estimates put the cost above a trillion dollars over fifty years. The spending went mostly to enforcement and prisons, and drug use did not fall.", "A 1981 law let the military share equipment and intelligence with police. SWAT deployments rose from a few thousand a year to tens of thousands, mostly to serve drug warrants." ], ref: ["Alexander, The New Jim Crow", "Comprehensive Crime Control Act (1984); Balko, Rise of the Warrior Cop", "The Sentencing Project, Locked Out 2020", "Anti-Drug Abuse Act (1988); Operation Just Cause (1989); Plan Colombia (2000)", "Anti-Drug Abuse Act (1986); Fair Sentencing Act (2010); First Step Act (2018)", "Fortune (Feb 2026); Center for American Progress fact sheet", "Military Cooperation with Law Enforcement Act (1981); Kraska and Kappeler, Militarizing American Police (1997)"] }, { n: "Gulf War", y: "1991", t: "1991", c: [48.5, 27.5], r: [414], v: "mnnlmml", deaths: { lo: 383, hi: 383, tag: OFF, note: "In theater: 148 in battle and 235 from other causes.", src: "va" }, cost: { b2011: 102, tag: OFF, note: "Gross cost. Allies reimbursed most of it; the net cost to US taxpayers was about $4.7 billion at the time.", src: "crs" }, all: null, d: [ "A six-week war with broad support and few direct effects at home. Its main legacy was making quick intervention look easy.", "No new restrictions at home, though press access was tightly managed through military pools.", "No change in voting or citizenship.", "Bush sent half a million troops before asking Congress and said he did not need its permission. Congress then voted narrowly to authorize.", ["Black troops were about 24 percent of those deployed, roughly twice their share of the population, and Colin Powell chaired the Joint Chiefs.", "Rodney King was beaten by Los Angeles police in March 1991, days after the ceasefire.", "The military remained one of the steadier paths into the middle class.", "Powell at the top and King on the pavement, in the same month, captured the two tracks."], "Saudi Arabia, Kuwait, Japan and Germany covered most of the cost. A brief recession followed, driven partly by the oil price spike.", "A 1990 defense law began transferring surplus military equipment to police for drug enforcement. It became the 1033 program in 1997." ], ref: ["Atkinson, Crusade: The Untold Story of the Persian Gulf War", "No source needed: no change recorded", "No source needed: no change recorded", "Authorization for Use of Military Force Against Iraq (Jan 1991)", "American Legion summary of Defense Department data; Christopher Commission report (1991)", "CRS, Costs of Major U.S. Wars, note b", "National Defense Authorization Act for FY1990–91, Section 1208"] }, { n: "Afghanistan", y: "2001–21", t: "2001", c: [66, 34], r: [4], v: "llmlmll", deaths: { lo: 2461, hi: 2461, tag: OFF, note: "Defense Department total for Enduring Freedom and Freedom's Sentinel, as widely reported.", src: "dod" }, cost: { bcur: 2300, tag: SCH, note: "Afghanistan and Pakistan war zone, in the dollars of the years spent. Not inflation-adjusted.", src: "brownCost" }, all: { text: "At least 940,000 killed by direct violence across all post-9/11 war zones combined.", src: "brownHuman" }, d: [ "The response to 9/11 built a surveillance and detention system that outlasted the war. The war itself ran twenty years.", "The Patriot Act expanded surveillance, and the NSA collected Americans' phone records in bulk until 2015. Guantanamo held detainees for years without trial.", "Formal rights did not change, but Muslim, Arab and South Asian communities faced registration programs, watchlists and informants in mosques.", "The 2001 authorization was a single sentence and has been used to justify operations in many countries. Drone strikes, including one on a US citizen, were ordered without court review.", ["Black Americans were more than 20 percent of Army recruits when the war began, well above their share of the population.", "Counterterror tools such as fusion centers were later used to monitor Black Lives Matter protests.", "Black recruits fell nearly 40 percent between 2001 and 2006, and the Black share of Army recruits dropped to about 12 percent.", "Barbara Lee, a Black congresswoman from Oakland, cast the only vote against the 2001 authorization."], "The war was paid for largely by borrowing instead of new taxes. Interest on that debt keeps growing after the fighting ended.", "Homeland Security grants gave local departments billions of dollars for equipment and training. Counterterrorism became part of ordinary policing." ], ref: ["Whitlock, The Afghanistan Papers", "USA PATRIOT Act (2001); USA FREEDOM Act (2015); Boumediene v. Bush (2008)", "National Security Entry-Exit Registration System (2002–11)", "Authorization for Use of Military Force (Sept 18, 2001)", "Associated Press on Pentagon recruiting data (June 2007)", "Brown University, Costs of War project", "Homeland Security Grant Program; Balko, Rise of the Warrior Cop"] }, { n: "Iraq War", y: "2003–11", t: "2003", c: [43, 34.5], r: [368], v: "llnllll", deaths: { lo: 4492, hi: 4492, tag: OFF, note: "Operation Iraqi Freedom 4,418 plus Operation New Dawn 74.", src: "dod" }, cost: { bcur: 2100, tag: SCH, note: "Iraq and Syria war zone, in the dollars of the years spent. Not inflation-adjusted.", src: "brownCost" }, all: { text: "At least 940,000 killed by direct violence across all post-9/11 war zones combined.", src: "brownHuman" }, d: [ "A war launched on false claims that cost trillions and deepened distrust of government.", "Justice Department memos approved torture, and Abu Ghraib showed the result. Secrecy claims expanded and whistleblowers were prosecuted.", "No change in voting or citizenship.", "The administration told Congress and the public that Iraq had weapons of mass destruction, and it did not. The 2002 authorization stayed on the books long after the war ended.", ["Opposition to the war ran far higher among Black Americans than among white Americans throughout.", "National Guard units and equipment were in Iraq when Katrina flooded New Orleans in 2005.", "Ferguson in 2014 put police militarization on the national agenda, and some equipment transfers were restricted the next year.", "Pentagon officials attributed the drop in Black enlistment largely to opposition to this war."], "Brown University's Costs of War project puts the post-9/11 wars at about 8 trillion dollars, including future care for veterans. That is money not spent on schools, housing or health.", "Mine-resistant vehicles built for Iraq were handed to local police through the 1033 program. They rolled out in Ferguson in 2014, which made the pipeline visible." ], ref: ["Iraq Survey Group (Duelfer) Report (2004)", "Office of Legal Counsel memos (2002); Taguba Report (2004)", "No source needed: no change recorded", "Authorization for Use of Military Force Against Iraq (2002); Senate Intelligence Committee report (2004)", "CBS News polling; Associated Press on Pentagon recruiting data (2007)", "Brown University, Costs of War project (2021)", "1033 program records; Executive Order 13688 (2015)"] } ]; return { SRC: SRC, LENS: LENS, WARS: WARS, CPI_FACTOR: 322.6 / 224.939 }; })(); (function () { var L = window.LEDGER, S = L.SRC, OFF = "Official count", SCH = "Scholarly estimate", ROUGH = "Rough estimate"; S.crsKosovo = { t: "Congressional Research Service, Kosovo and the 106th Congress (RL30729)", u: "https://www.everycrsreport.com/reports/RL30729.html", covers: "The 78-day air campaign of 1999, the $5.1 billion requested for it, no combat fatalities, and the House's 213-213 tie on authorizing the strikes." }; S.cfrLibya = { t: "Council on Foreign Relations, What Does Libya Cost the United States? (Aug 2011)", u: "https://www.cfr.org/articles/what-does-libya-cost-united-states", covers: "About $1.1 billion in direct US costs for the 2011 Libya intervention, tallied from Pentagon releases." }; S.pbsVen = { t: "PBS NewsHour / Associated Press, timeline of US military escalation against Venezuela (Jan 2026)", u: "https://www.pbs.org/newshour/world/a-timeline-of-u-s-military-escalation-against-venezuela-leading-to-maduros-capture", covers: "35 known strikes on boats killing at least 115 people from September 2025, the January 3, 2026 strikes on Caracas and capture of Nicolás Maduro, and the failed votes in Congress to require authorization." }; S.milVen = { t: "Military Times, US strikes Venezuela, says Nicolás Maduro has been captured (Jan 3, 2026)", u: "https://www.militarytimes.com/news/your-military/2026/01/03/us-strikes-venezuela-says-nicolas-maduro-has-been-captured/", covers: "No US deaths reported; Congress had not approved an authorization for the use of force in the region." }; S.iranWiki = { t: "2026 Iran war (Wikipedia summary of US, Iranian and UN figures)", u: "https://en.wikipedia.org/wiki/2026_Iran_war", covers: "Timeline from February 28, 2026, US casualties (19 service members killed per US figures), Iranian death tolls from several sources, and a $113.3 billion cost estimate as of June 2026." }; S.milIran = { t: "Military Times, 13 US troops killed, more than 380 wounded in Operation Epic Fury (Apr 8, 2026)", u: "https://www.militarytimes.com/news/your-military/2026/04/08/pentagon-data-13-us-troops-killed-346-wounded-in-operation-epic-fury/", covers: "Pentagon casualty database figures as of April 7, 2026." }; S.nprIran = { t: "NPR/PBS News/Marist poll on US military action in Iran (Mar 6, 2026)", u: "https://www.npr.org/2026/03/06/nx-s1-5737627/iran-us-military-poll-trump-approval", covers: "56 percent opposed overall; 68 percent of Black, 60 percent of Latino and 52 percent of white respondents opposed." }; S.abcIran = { t: "ABC News, Congress passes war powers resolution (June 2026)", u: "https://abcnews.com/Politics/senate-house-pass-war-powers-resolution-1st-time/story?id=134145998", covers: "The Senate adopted the Iran war powers resolution 50-48 after House passage. It does not carry the force of law." }; S.iranProtest = { t: "Protests against the 2026 Iran war (Wikipedia)", u: "https://en.wikipedia.org/wiki/Protests_against_the_2026_Iran_war", covers: "Scale of US protests and documented arrests, February through July 2026." }; var EARLY = "Too early to score."; var add = [ { n: "Kosovo air war", y: "1999", t: "1999", c: [21, 43.5], r: [688], v: "nnnlnnn", deaths: { lo: 2, hi: 2, tag: OFF, note: "No combat deaths. Two Army helicopter crew died in a training crash in Albania.", src: "crsKosovo" }, cost: { bcur: 5.1, tag: ROUGH, note: "Requested for the air campaign, munitions and readiness, in 1999 dollars.", src: "crsKosovo" }, all: { text: "Human Rights Watch counted about 500 Yugoslav civilians killed by NATO bombing.", src: null }, d: [ "A 78-day NATO bombing campaign with no US combat deaths and little trace at home. Its lasting mark is on war powers.", "No restrictions at home.", "No change in voting or citizenship.", "Clinton bombed for 78 days without authorization. The House tied 213 to 213 on approving the strikes, and a lawsuit by members of Congress was dismissed without a ruling on the merits.", ["Black service members took part as in any deployment of the period.", "No distinct effect at home.", "No distinct effect.", "A short air war fought by a small share of the force left little specific to record here."], "The cost was small against the defense budget and was paid from a supplemental spending bill.", "No change in policing at home." ], ref: ["CRS, Kosovo and the 106th Congress", "No source needed: no change recorded", "No source needed: no change recorded", "S.Con.Res. 21 (1999); Campbell v. Clinton (D.C. Cir. 2000)", "No source needed: no change recorded", "Emergency Supplemental Appropriations Act (P.L. 106-31, 1999)", "No source needed: no change recorded"] }, { n: "Libya intervention", y: "2011", t: "2011", c: [17, 28], r: [434], v: "nnnlnnn", deaths: { lo: 0, hi: 0, tag: OFF, note: "No US military deaths during the 2011 intervention.", src: "cfrLibya" }, cost: { bcur: 1.1, tag: SCH, note: "Direct costs tallied from Pentagon releases, in 2011 dollars.", src: "cfrLibya" }, all: null, d: [ "A seven-month NATO air campaign that toppled Qaddafi with no US deaths. At home it mattered mainly as a war powers precedent.", "No restrictions at home.", "No change in voting or citizenship.", "Obama kept the campaign going past the War Powers Resolution's 60-day limit, arguing that air strikes without ground troops were not hostilities. The House voted down an authorization and the strikes continued.", ["No distinct effect at home.", "No distinct effect.", "No distinct effect.", "Libya's collapse afterward reopened slave markets for African migrants, which drew protest from Black American leaders in 2017."], "At about $1.1 billion, the cost was less than a week of the Iraq or Afghanistan wars.", "No change in policing at home." ], ref: ["CRS, Operation Odyssey Dawn (Libya) (R41725)", "No source needed: no change recorded", "No source needed: no change recorded", "Office of Legal Counsel opinion (Apr 2011); House vote on H.J.Res. 68 (June 24, 2011)", "CNN reporting on Libyan slave auctions (Nov 2017)", "Council on Foreign Relations (Aug 2011)", "No source needed: no change recorded"] }, { n: "War against ISIS", y: "2014–present", t: "2014", c: [38, 36.5], r: [760], v: "mmnlnnm", deaths: { lo: 106, hi: 106, tag: OFF, note: "Operation Inherent Resolve, as of August 2021. The operation continues.", src: "dod" }, cost: { bcur: null, incl: true, tag: null, note: "Counted inside the Iraq War figure, which covers the whole Iraq and Syria war zone.", src: "brownCost" }, all: { text: "At least 940,000 killed by direct violence across all post-9/11 war zones combined.", src: "brownHuman" }, d: [ "An open-ended air and special operations war in Iraq and Syria, fought without a new vote in Congress. Its effects at home ran through terrorism policy more than through the war itself.", "Fear of ISIS-inspired attacks drove watchlists, informant operations and the 2017 travel ban, which the Supreme Court upheld. Courts and Congress also pushed back on some surveillance.", "No change in voting or citizenship.", "Three presidents have fought ISIS under the 2001 and 2002 authorizations, written before the group existed. Congress has never voted on this war.", ["No distinct pattern in who served.", "No distinct effect.", "No distinct effect.", "The domestic burden of this war fell mostly on Muslim and Arab American communities."], "The spending is real but folded into the wider Iraq and Syria totals, so it cannot be scored on its own.", "Limits on military gear for police were imposed in 2015 and lifted in 2017. Federal counter-extremism programs put local police into community monitoring." ], ref: ["CRS, U.S. War Costs, Casualties, and Personnel Levels Since 9/11 (IF11182)", "Trump v. Hawaii (2018); USA FREEDOM Act (2015)", "No source needed: no change recorded", "2001 and 2002 Authorizations for Use of Military Force; White House legal framework report (Dec 2016)", "Brennan Center reporting on Countering Violent Extremism programs", "Brown University, Costs of War project", "Executive Order 13688 (2015) and its 2017 revocation"] }, { n: "Venezuela strikes", y: "2025–26", t: "2025", c: [-65.5, 8], r: [862], v: "uuuluuu", recent: true, deaths: { lo: 0, hi: 0, tag: ROUGH, note: "No US deaths reported. Some personnel were reported hurt in the January 3 operation.", src: "milVen" }, cost: { bcur: null, tag: null, note: "No official estimate.", src: null }, all: { text: "At least 115 people killed in 35 known strikes on boats before January 2026, by administration announcements. Deaths in the January 3 strikes on Caracas are not confirmed.", src: "pbsVen" }, d: [ EARLY + " Strikes on alleged drug boats began in September 2025, and on January 3, 2026 US forces struck Caracas and captured Nicolás Maduro, who was flown to New York to face charges.", EARLY + " The administration designated several cartels as terrorist organizations and declared an armed conflict with them. What that changes inside the US is not yet clear.", EARLY + " No change in voting or citizenship is documented.", "The strikes rested on an administration memo declaring an armed conflict with drug cartels. Congress had not authorized force, and the Senate and House voted down measures that would have required its approval.", ["No breakdown of who served is available.", "Nothing documented yet.", "Nothing documented yet.", EARLY + " The campaign extends the drug war's framing, which is why it sits next to that entry."], EARLY + " A buildup of about 12,000 troops and a carrier group has no published price tag.", EARLY + " The terrorist designations widen the tools available against drug suspects, and the effect on policing at home is not yet documented." ], ref: ["PBS NewsHour / Associated Press timeline (Jan 2026)", "Executive order of Jan 20, 2025; State Department designations (Feb 2025)", "No source needed: no change recorded", "Senate votes of Oct 8 and Nov 6, 2025; House votes of Dec 17, 2025", "No source available yet", "PBS NewsHour / Associated Press timeline (Jan 2026)", "Executive order of Jan 20, 2025"] }, { n: "Iran war", y: "2026–", t: "2026", c: [54, 32], r: [364], v: "uuuluuu", recent: true, deaths: { lo: 19, hi: 19, tag: OFF, note: "19 service members and one contractor per US figures. The Pentagon database showed 13 as of April 7.", src: "iranWiki" }, cost: { bcur: 113.3, tag: ROUGH, note: "Estimate as of June 2026.", src: "iranWiki" }, all: { text: "Iran's government reports about 3,500 killed; US and Israeli officials claim more than 6,000 Iranian military dead. Deaths were also reported in Israel, Lebanon and several Gulf states.", src: "iranWiki" }, d: [ EARLY + " US and Israeli strikes began on February 28, 2026. A ceasefire took hold in April, and a June agreement broke down in July.", EARLY + " Antiwar protests led to arrests, including about 90 in Manhattan in April and more than 62 veterans at a House office building. No new speech or surveillance laws are documented.", EARLY + " No change is documented. In March the White House said a draft was not part of the current plan and did not rule one out.", "The strikes began without a vote in Congress. A Senate war powers resolution failed narrowly in March, and in June both chambers passed one that does not carry the force of law. The White House holds that hostilities ended with the April ceasefire.", ["No breakdown of casualties by race is published.", "Nothing documented yet.", "Nothing documented yet.", "In the first week, 68 percent of Black respondents opposed the strikes in an NPR/PBS/Marist poll, against 56 percent overall and 52 percent of white respondents."], EARLY + " The war cost an estimated $113 billion by June and caused the largest disruption of global oil supply on record. Lasting effects at home cannot be measured yet.", EARLY + " Cities raised security at sensitive sites. No lasting change is documented." ], ref: ["2026 Iran war (Wikipedia summary)", "Protests against the 2026 Iran war (Wikipedia summary)", "White House statement of Mar 16, 2026", "ABC News on the Senate's 50-48 vote (June 2026)", "NPR/PBS News/Marist poll (Mar 2026)", "2026 Iran war (Wikipedia summary)", "NYPD statement of Mar 2, 2026"] } ]; L.WARS.forEach(function (w) { if (w.n === "Gulf War") w.c = [49, 25.5]; if (w.n === "Iraq War") w.c = [44.5, 32.5]; }); L.WARS = L.WARS.concat(add).sort(function (a, b) { return Number(a.t) - Number(b.t); }); })();